<?php require 'admin_bootstrap.php'; $title='Schedule Management'; $subjects=$pdo->query("SELECT * FROM subjects ORDER BY code")->fetchAll(); $faculty=$pdo->query("SELECT * FROM users WHERE role='faculty' ORDER BY name")->fetchAll(); $offerings=$pdo->query("SELECT o.*,s.code,s.name subject,f.name faculty_name FROM subject_offerings o JOIN subjects s ON s.id=o.subject_id LEFT JOIN users f ON f.id=o.faculty_id ORDER BY FIELD(o.day_name,'Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'),o.start_time,s.code")->fetchAll(); require 'header.php'; admin_flash_html(); ?>
<section class="section"><div class="card-head"><div><span class="eyebrow">SECTIONS</span><h2>Schedule &amp; Section Management</h2></div></div>
<form method="post"><?=admin_form_return('admin_schedules.php')?><input type="hidden" name="action" value="add_offering"><div class="register-grid"><div class="field"><label>Subject</label><select name="subject_id" required><option value="">Select subject</option><?php foreach($subjects as $s): ?><option value="<?=$s['id']?>"><?=e($s['code'].' — '.$s['name'])?></option><?php endforeach; ?></select></div><div class="field"><label>Faculty</label><select name="faculty_id"><option value="0">Unassigned</option><?php foreach($faculty as $f): ?><option value="<?=$f['id']?>"><?=e($f['name'])?></option><?php endforeach; ?></select></div><div class="field"><label>Day</label><select name="day_name"><option>Monday</option><option>Tuesday</option><option>Wednesday</option><option>Thursday</option><option>Friday</option><option>Saturday</option></select></div><div class="field"><label>Section</label><input name="section" placeholder="CPE-2A" required></div><div class="field"><label>Start Time</label><input type="time" name="start_time" required></div><div class="field"><label>End Time</label><input type="time" name="end_time" required></div><div class="field"><label>Room</label><input name="room" placeholder="Room 301" required></div></div><button class="btn">Create Schedule</button></form></section>
<section class="section"><div class="card-head"><div><span class="eyebrow">AVAILABLE SECTIONS</span><h2>Current Schedules</h2></div><span class="muted"><?=count($offerings)?> schedules</span></div><div class="table-scroll"><table class="table"><tr><th>Subject</th><th>Section</th><th>Schedule</th><th>Teacher</th><th>Room</th><th></th></tr><?php foreach($offerings as $o): ?><tr><td><b><?=e($o['code'])?></b><br><?=e($o['subject'])?></td><td><?=e($o['section'])?></td><td><?=e($o['day_name'])?><br><?=date('g:i A',strtotime($o['start_time']))?>–<?=date('g:i A',strtotime($o['end_time']))?></td><td><?=e($o['faculty_name']?:'Unassigned')?></td><td><?=e($o['room'])?></td><td><form method="post"><?=admin_form_return('admin_schedules.php')?><input type="hidden" name="action" value="delete_offering"><input type="hidden" name="offering_id" value="<?=$o['id']?>"><button class="btn danger-btn" onclick="return confirm('Remove this schedule/section?')">Remove</button></form></td></tr><?php endforeach; ?></table></div></section>
<?php require 'footer.php'; ?>
